#!/usr/bin/env python3
"""Generates the instance-side witness matrix fixture (#536 step 3) and its
expected output, which is computed here from the rules of World::witnesses,
not taken from a run.

  gen_matrix.py TARGET OUT.qz OUT.out      TARGET: class_scoped | class_top | class_args | generic_scoped | generic_top | abstract | module
"""
import sys

HEADER = """# The #536 step 3 witness matrix, instance side, target `{target}`{note}
# (generated by tools/witness-matrix.py; the class side is
# witness_matrix_class/_generic/_abstract,
# the cross-cog column is in cogs.rs, the refusals in diagnostics.rs):
# conformance path x witness source x requirement x module arguments x
# scope of the extension, each cell printing what runs through a value
# typed `M` in a function at the top level (elsewhere, for a scoped
# extension), through one in the extension's module (where it is
# active), and for a direct call on a receiver typed as the conforming
# class where the extension is active. The expected output was computed
# from the rules, not taken from a run. For a class `K` that has `M`
# only through an extension `E` hanging from `C` on its chain, a call
# through `M` runs: (1) below `C`, the first method of `K`'s lookup order
# that replaces it (a subclass's own, one of a module it includes); (2)
# `E`'s own method; (3) the first of `C`'s own part of the order (its
# own methods, the modules it includes itself); (4) one of a module `E`
# includes after it; (5) the nearest in the included module's own
# ancestry; (6) the module's own body, an abstract one being implemented
# by what follows (a module `E` includes before it, an inherited
# method). For a module target, the including class's own method comes
# before the extension's. A direct call where the extension is active
# runs the extension's own method when it has one (chosen statically,
# also on a subclass's value typed as the class), else what the call
# through `M` runs. An own include (path `own`) goes by ordinary
# dispatch.
# Skipped as identical by the rules or not expressible:
{skipped}"""

SKIPPED = {
    "class": [
        "args param: no class parameter to pass (generic target)",
        "args concrete beyond the reduced list of _class_args, and the reduced lists of the subclass paths: the same rule cell by cell as path ext x args none (one file per scope keeps the checker's time down)",
        "path own x witness ext/emod/nmod/prev: no extension (cell 1's extension method is in extension_own_include_method)",
        "witness default/prev x requirement abstract: nothing implements it (#600), or the cell is `prev`",
        "the gated sends (`sort`, `clamp`): they look the name up first (#599)",
        "an inference variable as the module's argument: the conformance is declared with written arguments; the call sites infer `T <: M` in witness_matrix_generic",
    ],
    "generic": [
        "path own: as the class target",
        "paths sub_own_ext, ext_sub_inc: as the class target",
        "the subclass paths beyond a reduced list: the same rule as path ext (one file per scope keeps the checker's time down)",
        "the direct call column for args param x witness sup: as concrete",
    ],
    "abstract": [
        "path own, sub_own_ext, ext_sub_inc: as the class target",
        "args concrete/param: as the class and generic targets",
    ],
    "module": [
        "witness sup: a module has no superclass",
        "witness inc: a module the including class includes is `cls` one entry later",
        "the direct call column where both the class and the extension define the method: the extension is of the module, the method the class's own; not a witness question",
        "args concrete/param, paths sub_own_ext/ext_sub_inc: as the class target",
    ],
}

n = 0
out_qz = []
out_exp = []


def cell(target, path, wit, req, args, scope):
    """Emit one cell; returns nothing. wit is a set of sources."""
    global n
    i = n
    n += 1
    generic_m = args in ("concrete", "param")
    mp = "[T]" if generic_m else ""
    par_m = "(x: T)" if generic_m else ""
    call = "(1)" if generic_m else ""
    # The argument type as the class and the extension write it.
    if args == "concrete":
        aty, marg = "Int", "[Int]"
    elif args == "param":
        aty, marg = "U", "[U]"
    else:
        aty, marg = None, ""
    par_c = f"(x: {aty})" if generic_m else ""
    cp = "[U]" if target == "generic" else ""
    inst = "[Int]" if target == "generic" else ""
    # What `M` is called with at the call sites.
    mty = f"M{i}" + ("[Int]" if generic_m else "")
    L = []
    w = L.append
    # The module.
    w(f"module M{i}{mp}")
    if req == "abstract":
        w(f"  abstract def m{par_m} -> String")
    else:
        w(f"  def m{par_m} -> String = \"M\"")
    w("end")
    if "nmod" in wit:
        w(f"module N{i}{mp}")
        w(f"  include M{i}{mp}")
        w(f"  def m{par_m} -> String = \"N\"")
        w("end")
    if "emod" in wit:
        w(f"module E{i}{mp}")
        w(f"  def m{par_m} -> String = \"E2\"")
        w("end")
    if "prev" in wit:
        w(f"module P{i}{mp}")
        w(f"  def m{par_m} -> String = \"E0\"")
        w("end")
    if "inc" in wit:
        w(f"module I{i}{cp if args == 'param' else ''}")
        w(f"  def m{par_c} -> String = \"inc\"")
        w("end")
    own_include = path == "own"
    # The conforming class and its surroundings.
    sup = "sup" in wit
    if sup:
        w(f"class B{i}{cp}")
        w("  def initialize; end")
        w(f"  def m{par_c} -> String = \"sup\"")
        w("end")
    if target == "module":
        w(f"module T{i}")
        if "own" in wit:
            w(f"  def m{par_c} -> String = \"T\"")
        w("end")
        w(f"class C{i}")
        w(f"  include T{i}")
        w("  def initialize; end")
        if "cls" in wit:
            w(f"  def m{par_c} -> String = \"cls\"")
        w("end")
        tname = f"T{i}"
        ext_target = f"T{i}"
    else:
        if target == "abstract":
            head = f"abstract class A{i}"
            tname = f"A{i}"
        else:
            head = f"class C{i}{cp}"
            tname = f"C{i}"
        if sup:
            head += f" < B{i}{cp}"
        w(head)
        if own_include:
            w(f"  include M{i}{marg}")
        if "inc" in wit:
            w(f"  include I{i}{cp if args == 'param' else ''}")
        w("  def initialize; end")
        if "own" in wit:
            w(f"  def m{par_c} -> String = \"own\"")
        w("end")
        if target == "abstract":
            w(f"class C{i} < A{i}")
            w("  def initialize; end")
            w("end")
        ext_target = tname + cp
    # The subclass of the path.
    recv = f"C{i}{inst}"
    if path in ("ext_sub", "ext_sub_own", "ext_sub_inc", "sub_own_ext"):
        if path == "ext_sub_inc":
            w(f"module L{i}")
            w(f"  def m{par_c} -> String = \"subinc\"")
            w("end")
        w(f"class S{i}{cp} < C{i}{cp}")
        if path == "ext_sub_inc":
            w(f"  include L{i}")
        w("  def initialize; end")
        if path == "ext_sub_own":
            w(f"  def m{par_c} -> String = \"sub\"")
        w("end")
        recv = f"S{i}{inst}"
    # The extension.
    ind = "  " if scope == "scoped" else ""
    cty = f"C{i}{inst}"
    if not own_include:
        if scope == "scoped":
            w(f"module X{i}")
        w(f"{ind}extension {ext_target}")
        if "prev" in wit:
            w(f"{ind}  include P{i}{marg}")
        if "nmod" in wit:
            w(f"{ind}  include N{i}{marg}")
        else:
            w(f"{ind}  include M{i}{marg}")
        if "emod" in wit:
            w(f"{ind}  include E{i}{marg}")
        if "ext" in wit:
            w(f"{ind}  def m{par_c} -> String = \"ext\"")
        w(f"{ind}end")
        if path == "sub_own_ext":
            w(f"{ind}extension S{i}{cp}")
            w(f"{ind}  include M{i}{marg}")
            w(f"{ind}  def m{par_c} -> String = \"subext\"")
            w(f"{ind}end")
        if scope == "scoped":
            w(f"  def self.up(x: {cty}) -> {mty} = x")
            w(f"  def self.via(x: {mty}) -> String = x.m{call}")
            w(f"  def self.direct(x: {cty}) -> String = x.m{call}")
            w("end")
        else:
            w(f"def up{i}(x: {cty}) -> {mty} = x")
            w(f"def direct{i}(x: {cty}) -> String = x.m{call}")
    else:
        w(f"def up{i}(x: {cty}) -> {mty} = x")
        w(f"def direct{i}(x: {cty}) -> String = x.m{call}")
    w(f"def via{i}(x: {mty}) -> String = x.m{call}")
    label = f"{target}/{path}/{'+'.join(sorted(wit))}/{req}/{args}/{scope}"
    if not own_include and scope == "scoped":
        up, via_in, direct = f"X{i}.up", f"X{i}.via", f"X{i}.direct"
    else:
        up, via_in, direct = f"up{i}", f"via{i}", f"direct{i}"
    typed, lexical = expect(target, path, wit, req)
    cols = [f"#{{via{i}({up}({recv}.new))}}", f"#{{{via_in}({up}({recv}.new))}}"]
    exp = [typed, typed]
    if lexical is not None:
        cols.append(f"#{{{direct}({recv}.new)}}")
        exp.append(lexical)
    w(f"puts \"{label}: {' '.join(cols)}\"")
    out_qz.extend(L)
    out_exp.append(f"{label}: {' '.join(exp)}")


def expect(target, path, wit, req):
    """What the rules say runs: (through M, direct call typed as the class)."""
    # At the class the conformance hangs from.
    if path == "own":
        # Ordinary dispatch: the class's own, an own include's (included
        # after `M`, so in front), the module's body, an inherited method
        # for an abstract one.
        if "own" in wit:
            at_c = "own"
        elif "inc" in wit:
            at_c = "inc"
        elif req == "default":
            at_c = "M"
        else:
            at_c = "sup"
        return at_c, at_c
    if target == "module" and "cls" in wit:
        at_c = "cls"
    elif "ext" in wit:
        at_c = "ext"
    elif "own" in wit:
        at_c = "T" if target == "module" else "own"
    elif "inc" in wit:
        at_c = "inc"
    elif "emod" in wit:
        at_c = "E2"
    elif "nmod" in wit:
        at_c = "N"
    elif req == "default":
        at_c = "M"
    elif "prev" in wit:
        at_c = "E0"
    elif "sup" in wit:
        at_c = "sup"
    else:
        raise SystemExit(f"nothing implements the cell {target}/{path}/{wit}/{req}")
    below = {"ext_sub_own": "sub", "ext_sub_inc": "subinc", "sub_own_ext": "subext"}.get(path)
    typed = below or at_c
    # The direct call where the extension is active, the receiver typed as
    # the conforming class: the extension's own method statically.
    if target == "module" and "cls" in wit and "ext" in wit:
        lexical = None
    elif "ext" in wit and not (target == "module" and "cls" in wit):
        lexical = "ext"
    elif path == "sub_own_ext":
        # The subclass's own extension is not one of the class the call is
        # typed as: the class's method runs, by ordinary dispatch, and an
        # extension's method overrides nothing.
        lexical = at_c
    else:
        lexical = typed
    return typed, lexical


def main():
    target, qz, exp = sys.argv[1:4]
    scopes = ["scoped", "top"]
    if target in ("class_scoped", "class_top", "class_args"):
        variant, target = target, "class"
        full = [({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                ({"own"}, "default"), ({"inc"}, "abstract"), ({"inc"}, "default"),
                ({"sup"}, "abstract"), ({"sup"}, "default"), ({"emod"}, "abstract"),
                ({"emod"}, "default"), ({"nmod"}, "abstract"), ({"nmod"}, "default"),
                (set(), "default"), ({"prev"}, "abstract"), ({"prev"}, "default"),
                ({"ext", "own"}, "abstract"), ({"ext", "inc"}, "default"),
                ({"own", "inc"}, "abstract"), ({"own", "emod"}, "default"),
                ({"emod", "sup"}, "abstract"), ({"ext", "emod"}, "default")]
        if variant == "class_args":
            # The module's arguments: concrete ones, a reduced list.
            for wit, req in (({"own"}, "abstract"), (set(), "default"), ({"sup"}, "abstract")):
                cell(target, "own", wit, req, "concrete", "none")
            for scope in scopes:
                for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), ({"inc"}, "abstract"),
                                 ({"sup"}, "abstract"), ({"emod"}, "abstract"), ({"nmod"}, "default"),
                                 (set(), "default"), ({"prev"}, "abstract")):
                    cell(target, "ext", wit, req, "concrete", scope)
                for wit, req in (({"ext"}, "abstract"), ({"own"}, "abstract"), (set(), "default")):
                    cell(target, "ext_sub_own", wit, req, "concrete", scope)
        else:
            scope = "scoped" if variant == "class_scoped" else "top"
            if scope == "scoped":
                # Path own (control): no extension, so once.
                for wit, req in (({"own"}, "abstract"), ({"own"}, "default"), (set(), "default"),
                                 ({"inc"}, "abstract"), ({"own", "inc"}, "default"),
                                 ({"sup"}, "abstract"), ({"sup"}, "default")):
                    cell(target, "own", wit, req, "none", "none")
            for wit, req in full:
                cell(target, "ext", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), ({"sup"}, "abstract"),
                             ({"emod"}, "abstract"), (set(), "default")):
                cell(target, "ext_sub", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                             ({"inc"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                             ({"nmod"}, "default"), (set(), "default"), ({"prev"}, "abstract")):
                cell(target, "ext_sub_own", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "default"), (set(), "default"),
                             ({"sup"}, "abstract")):
                cell(target, "ext_sub_inc", wit, req, "none", scope)
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract")):
                cell(target, "sub_own_ext", wit, req, "none", scope)
    elif target in ("generic_scoped", "generic_top"):
        scope = "scoped" if target == "generic_scoped" else "top"
        target = "generic"
        for args in ("none", "concrete", "param"):
            for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                             ({"own"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                             ({"nmod"}, "default"), (set(), "default"),
                             ({"ext", "own"}, "default")):
                cell(target, "ext", wit, req, args, scope)
            for wit, req in (({"ext"}, "abstract"), (set(), "default")):
                cell(target, "ext_sub", wit, req, args, scope)
            for wit, req in (({"ext"}, "abstract"), ({"own"}, "abstract"), ({"emod"}, "abstract"),
                             (set(), "default")):
                cell(target, "ext_sub_own", wit, req, args, scope)
    elif target == "abstract":
        for scope in scopes:
            for path in ("ext", "ext_sub", "ext_sub_own"):
                for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                                 ({"own"}, "default"), ({"sup"}, "abstract"), ({"emod"}, "abstract"),
                                 ({"nmod"}, "default"), (set(), "default"), ({"ext", "own"}, "abstract")):
                    cell(target, path, wit, req, "none", scope)
    elif target == "module":
        for scope in scopes:
            for path in ("ext", "ext_sub", "ext_sub_own"):
                for wit, req in (({"ext"}, "abstract"), ({"ext"}, "default"), ({"own"}, "abstract"),
                                 ({"own"}, "default"), ({"cls"}, "abstract"), ({"cls"}, "default"),
                                 ({"cls", "ext"}, "abstract"), ({"cls", "own"}, "default"),
                                 ({"ext", "own"}, "abstract"), ({"emod"}, "abstract"),
                                 ({"nmod"}, "default"), (set(), "default")):
                    cell(target, path, wit, req, "none", scope)
    else:
        raise SystemExit("target?")
    skipped = "\n".join(f"# - {s}" for s in SKIPPED[target])
    variant = sys.argv[1]
    note = {"class_scoped": " (scoped extensions; top-level ones: witness_matrix_instance_class_top; the module's arguments: _class_args)",
            "class_top": " (top-level extensions)",
            "class_args": " (the module's arguments, both scopes)",
            "generic_scoped": " (scoped extensions; top-level ones: witness_matrix_instance_generic_top)",
            "generic_top": " (top-level extensions)"}.get(variant, "")
    with open(qz, "w") as f:
        f.write(HEADER.format(target=target, note=note, skipped=skipped) + "\n" + "\n".join(out_qz) + "\n")
    with open(exp, "w") as f:
        f.write("\n".join(out_exp) + "\n")


main()
